import { animate, stagger, createSpring } from 'animejs';
export function mountNeuralNetworkGraphPropagator(root) {
  const controller = new AbortController(); const signal = controller.signal; let timer;
  let motion;const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');const run=(target,options)=>{motion?.pause();if(!reduced.matches)motion=animate(target,options);};signal.addEventListener('abort',()=>motion?.pause(),{once:true});const options=Array.from(root.querySelectorAll('[data-item]'));const output=root.querySelector('[data-output]');const copy=root.querySelector('[data-copy]');const status=root.querySelector('[role="status"]');const scene=root.querySelector('[data-scene]');let selected=0;const render=(message)=>{options.forEach((option,index)=>option.setAttribute('aria-pressed',String(index===selected)));output.textContent=options[selected].textContent;copy.textContent=message;status.textContent=message;run(scene.children,{opacity:[0,1],y:[12,0],delay:stagger(45),duration:360,ease:'outCubic'});};options.forEach((option,index)=>option.addEventListener('click',()=>{selected=index;render('Etapa actualizada: '+option.textContent);},{signal}));root.querySelector('[data-primary]').addEventListener('click',()=>{selected=(selected+1)%options.length;render('Predicción calculada: '+options[selected].textContent);},{signal});root.querySelector('[data-reset]').addEventListener('click',()=>{selected=0;render('Red preparada');},{signal});render('Red preparada');
  return () => { controller.abort(); clearTimeout(timer); };
}
// Montaje: document.querySelectorAll('[data-cxd-control="neural-network-graph-propagator"]').forEach(mountNeuralNetworkGraphPropagator);
